import unitData from "../../../../data/autobattler/units.json";

// =========================================================
// SHADOW ARENA - static game data (units, Boss routes,
// synergies, keyword texts). Pure data: imported by the engine
// (browser + server replay) and by the UI.
//
// data/autobattler/units.json is generated by
// data/autobattler/build-units.mjs from the local card catalog.
// =========================================================

export type Attribute =
  | "DARK"
  | "LIGHT"
  | "EARTH"
  | "WATER"
  | "FIRE"
  | "WIND";

export type Tribe =
  | "Dragon"
  | "Spellcaster"
  | "Warrior"
  | "Fiend"
  | "Zombie"
  | "Machine"
  | "Beast"
  | "Aqua";

export type Ability =
  | "taunt"
  | "shield"
  | "revive"
  | "pierce"
  | "rally"
  | "lastwill"
  | "spawn"
  | "double"
  | "venom"
  | "ascend"
  | "ambush";

export type CombatKeyword =
  Exclude<
    Ability,
    "rally" | "ascend"
  >;

export type UnitDef = {
  id: string;
  name: string;
  tier: number;
  attribute: Attribute;
  race: string;
  tribe: Tribe | null;
  level: number;
  cardAtk: number;
  cardDef: number;
  atk: number;
  hp: number;
  ability: Ability;
  power: number;
  rallyBy?: "tribe" | "attribute";
  img: string;
  art: string | null;
};

export type BossRouteUnit = {
  name: string;
  attribute: string | null;
  race: string | null;
  level: number;
  cardAtk: number;
  cardDef: number;
  boss: boolean;
  img: string;
  art: string | null;
};

export type BossRoute = {
  code: string;
  name: string;
  order: number;
  keywords: CombatKeyword[];
  units: BossRouteUnit[];
};

const data =
  unitData as unknown as {
    units: UnitDef[];
    routes: BossRoute[];
  };

export const UNITS: readonly UnitDef[] =
  data.units;

export const ROUTES: readonly BossRoute[] =
  [...data.routes].sort(
    (a, b) => a.order - b.order
  );

export const UNIT_BY_ID: ReadonlyMap<string, UnitDef> =
  new Map(
    UNITS.map(
      (unit) => [unit.id, unit]
    )
  );

export const ROUTE_BY_CODE: ReadonlyMap<string, BossRoute> =
  new Map(
    ROUTES.map(
      (route) => [route.code, route]
    )
  );

export const ATTRIBUTES: readonly Attribute[] = [
  "DARK",
  "LIGHT",
  "EARTH",
  "WATER",
  "FIRE",
  "WIND",
];

export const TRIBES: readonly Tribe[] = [
  "Dragon",
  "Spellcaster",
  "Warrior",
  "Fiend",
  "Zombie",
  "Machine",
  "Beast",
  "Aqua",
];

export const ABILITY_LABEL: Record<Ability, string> = {
  taunt: "Guardian",
  shield: "Spellbound",
  revive: "Reborn",
  pierce: "Pierce",
  rally: "Rally",
  lastwill: "Last Will",
  spawn: "Summon",
  double: "Double Attack",
  venom: "Venom",
  ascend: "Ascend",
  ambush: "Ambush",
};

/** One-line rules text for a unit's ability (golden = doubled power). */
export function abilityText(
  ability: Ability,
  power: number,
  extra?: {
    rallyBy?: "tribe" | "attribute";
    tribe?: Tribe | null;
    attribute?: string | null;
  }
) {
  switch (ability) {
    case "taunt":
      return "Guardian: enemies must attack this first.";
    case "shield":
      return "Spellbound: the first hit it takes deals no damage.";
    case "revive":
      return "Reborn: the first time it dies, it returns with 1 health.";
    case "pierce":
      return "Pierce: excess damage hits the enemy next to its target.";
    case "rally": {
      const group =
        extra?.rallyBy === "tribe"
          ? extra.tribe ?? "same-type"
          : extra?.attribute ?? "same-attribute";

      return `Rally: when played, give your other ${group} units +${power}/+${power}.`;
    }
    case "lastwill":
      return `Last Will: when it dies, give a random ally +${power}/+${power}.`;
    case "spawn":
      return `Summon: when it dies, summon a ${power}/${power} Token.`;
    case "double":
      return "Double Attack: attacks twice each time.";
    case "venom":
      return "Venom: destroys any unit it damages.";
    case "ascend":
      return `Ascend: at the end of your turn, gain +${power}/+${power}.`;
    case "ambush":
      return `Ambush: at the start of combat, deal ${power} damage to a random enemy.`;
  }
}

